import{_ as r,o as e,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CDS G/H (Day 1) - Erasure Coding Update","description":"","frontmatter":{"title":"CDS G/H (Day 1) - Erasure Coding Update","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-25T00:00:00.000Z","tags":["Erasure Coding","Ceph","Distributed Storage","Optimization","Performance"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_Erasure_Coding_Update.md","filePath":"posts/2014/CDS_G_H_Day_1_-_Erasure_Coding_Update.md","lastUpdated":1780459816000}'),t={name:"posts/2014/CDS_G_H_Day_1_-_Erasure_Coding_Update.md"};function o(s,a,n,d,u,g){return e(),i("div",null,[...a[0]||(a[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间： <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间：&quot;">​</a></h4><p>（未提及具体时间）</p><h4 id="会议地点" tabindex="-1">会议地点： <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点：&quot;">​</a></h4><p>（未提及具体地点）</p><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>（未提及具体姓名）</li><li>Veronica（负责Google Summer of Code项目及相关工作）</li><li>L（负责Erasure Coding插件优化）</li><li>Andreas（负责Isa插件原型）</li></ul><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><ol><li><p><strong>Erasure Coding插件优化</strong></p><ul><li><strong>初始问题</strong>：Erasure Coding的初始代码支持方式较为奇怪，因为没有初始配置文件。</li><li><strong>改进计划</strong>：将提交一个pending pull request，添加对通用AR配置文件的支持，以便定义针对QA、本地可修复代码或其他参数变体的作业。</li><li><strong>插件性能</strong>：目前主要关注稳定化插件并进行了基准测试，但尚未对性能不佳的部分进行优化。</li><li><strong>ARM处理器性能</strong>：讨论了ARM处理器上的性能问题，特别是对于冷存储应用。希望有人能够提供ARM机器进行基准测试。</li></ul></li><li><p><strong>JF Complete维护和贡献</strong></p><ul><li><strong>当前状态</strong>：SEF中已同步最新稳定版本。</li><li><strong>待解决问题</strong>：一个pending pull request（ticket 8071）正在测试中。</li></ul></li><li><p><strong>本地可修复代码</strong></p><ul><li><strong>基准测试</strong>：已进行基准测试，但未分析调用图以确定4K和1MB解码之间的差异。</li><li><strong>性能问题</strong>：存在显著的性能差异，但仍然足够好。</li></ul></li><li><p><strong>Isa插件原型</strong></p><ul><li><strong>实现</strong>：Andreas已成功实现了一个插件，该插件在Intel CPU上比Gaser更快。</li><li><strong>包装问题</strong>：需要确定如何打包该库，因为它可以以静态库或共享库的形式提供。</li></ul></li><li><p><strong>可靠性模型和代码</strong></p><ul><li><strong>当前状态</strong>：Veronica正在尝试根据当前模型的假设实现Rados Erasure Code。</li><li><strong>基准测试工具</strong>：提到了一个用于基准测试Erasure Code的CPU开销的工具。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>对Erasure Coding插件进行优化，并关注ARM处理器上的性能。</li><li>继续维护和贡献JF Complete。</li><li>对本地可修复代码进行基准测试和分析。</li><li>将Isa插件原型集成到JF中。</li><li>Veronica将继续研究可靠性模型和代码。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>L将继续优化Erasure Coding插件。</li><li>Veronica将继续研究可靠性模型和代码。</li><li>Andreas将解决Isa插件的包装问题，并尝试将其集成到JF中。</li><li>所有参与者将关注ARM处理器上的性能问题。</li></ul>',13)])])}const h=r(t,[["render",o]]);export{p as __pageData,h as default};
